"""Stage C6: requirements generated by Reframe from Claude's results, in AWS Transform's shape (docs/pipeline-2.md).

The plugin writes rule cards, not requirements. Reframe asks Claude, once per domain the plugin found and with Reframe's
own prompt, to turn that domain's results (its modules, flows, rule cards and SME questions, and nothing of AWS
Transform's) into business functions, capabilities (user stories) and requirements with their EARS pattern, each
citing the rule cards behind it. Reframe then checks every citation: a requirement that cites neither a rule card the
plugin wrote nor a file and line that exist in the snapshot is dropped and counted. Everything here is labelled as
generated by Reframe from Claude's results, and kept in outputs/claude/requirements.json, apart from the plugin's files.
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from reframe.claude.runner import ClaudeCode
from reframe.core.errors import Outcome, Stop
from reframe.core.runfolder import RunFolder, iso

LABEL = "generated by Reframe from Claude's results"
PATTERNS = ["ubiquitous", "event-driven", "state-driven", "unwanted behaviour", "optional feature", "complex"]
CITATION = re.compile(r"^([^:\s]+):(\d+)(?:-(\d+))?$")

SCHEMA = {
    "type": "object", "required": ["functions"],
    "properties": {"functions": {"type": "array", "items": {
        "type": "object", "required": ["name", "description", "capabilities"],
        "properties": {
            "name": {"type": "string"}, "description": {"type": "string"},
            "capabilities": {"type": "array", "items": {
                "type": "object", "required": ["title", "story", "requirements"],
                "properties": {
                    "title": {"type": "string"}, "story": {"type": "string"},
                    "requirements": {"type": "array", "items": {
                        "type": "object", "required": ["kind", "pattern", "text", "rules"],
                        "properties": {"kind": {"type": "string", "enum": ["functional", "non-functional"]},
                                       "pattern": {"type": "string", "enum": PATTERNS},
                                       "text": {"type": "string"},
                                       "rules": {"type": "array", "items": {"type": "string"}},
                                       "sources": {"type": "array", "items": {"type": "string"}}}}},
                    "questions": {"type": "array", "items": {
                        "type": "object", "required": ["text", "owner"],
                        "properties": {"text": {"type": "string"}, "owner": {"type": "string"}, "rule": {"type": "string"}}}}}}}}}}},
}

PROMPT = """You are helping Reframe turn the results of Claude's code-modernization plugin into requirements a business user can review.

Read {input}. It holds one domain of a legacy system as the plugin described it: the domain, its modules, the business flows that pass through it, its business rule cards (each with an ID such as RULE-012, a Given/When/Then specification and a source file and line), and the plugin's open questions for subject-matter experts.

Write that domain's business functions, in the shape AWS Transform uses:
- a business function is something the business does (for example "Card authorization"), with a one- or two-sentence description;
- each function has capabilities, each written as a user story ("As a ..., I want ..., so that ...") with a short title;
- each capability has requirements, each one sentence in EARS form ("The system shall ...", "When ..., the system shall ...", "While ..., the system shall ...", "If ..., then the system shall ...", "Where ..., the system shall ..."), with its kind (functional or non-functional) and EARS pattern;
- every requirement lists the rule card IDs it comes from in "rules", and may add "file:line" citations in "sources";
- capabilities may carry the open questions that apply to them, each with the role that should answer it (the owner), and the rule ID it concerns.

Use only what is in the file. Do not invent behaviour, values, systems or rules. Every requirement must come from at least one rule card in the file. Cover every rule card at least once. Keep the plugin's wording of values and conditions. Answer only with the JSON."""


def domain_input(model: dict[str, Any], domain: dict[str, Any]) -> dict[str, Any]:
    modules = [m for m in model.get("modules") or [] if m.get("domain") == domain["id"]]
    names = {m.get("name", "").upper() for m in modules}
    members = set(domain.get("members") or [])
    rules = [r for r in model.get("rules") or [] if r.get("domain") == domain["id"] or r.get("program", "").upper() in names]
    rule_ids = {r["id"] for r in rules}
    flows = [f for f in model.get("flows") or [] if any(set(s.get("nodes") or []) & members for s in f.get("steps") or [])]
    return {
        "domain": {"name": domain.get("name"), "description": domain.get("description", "")},
        "modules": [{"name": m.get("name"), "file": m.get("file"), "language": m.get("language"), "lines": m.get("loc")} for m in modules],
        "flows": flows,
        "rules": [{k: r.get(k) for k in ("id", "name", "category", "priority", "plain", "spec", "parameters", "edge_cases", "defect",
                                         "confidence", "source")} for r in rules],
        "questions": [q for q in model.get("sme_questions") or [] if q.get("rule") in rule_ids],
    }


def file_lines(legacy: Path) -> dict[str, int]:
    out = {}
    for path in legacy.rglob("*"):
        if path.is_file():
            try:
                out[str(path.relative_to(legacy))] = sum(1 for _ in path.open("rb"))
            except OSError:
                continue
    return out


def valid_source(citation: str, lines: dict[str, int]) -> bool:
    match = CITATION.match(citation.strip().strip("`"))
    if not match:
        return False
    path, start = match.group(1), int(match.group(2))
    total = lines.get(path) or next((n for p, n in lines.items() if p.endswith("/" + path)), 0)
    return 0 < start <= total


def check(raw: dict[str, Any], known_rules: set[str], lines: dict[str, int]) -> tuple[list[dict[str, Any]], int]:
    """Keep each requirement whose rule IDs (those the plugin wrote) or file:line citations hold; count the rest."""
    dropped = 0
    functions = []
    for function in raw.get("functions") or []:
        caps = []
        for cap in function.get("capabilities") or []:
            requirements = []
            for req in cap.get("requirements") or []:
                rules = [r for r in req.get("rules") or [] if r in known_rules]
                sources = [s for s in req.get("sources") or [] if valid_source(s, lines)]
                if not rules and not sources:
                    dropped += 1
                    continue
                requirements.append({**req, "rules": rules, "sources": sources})
            if requirements:
                questions = [{**q, "rule": q.get("rule") if q.get("rule") in known_rules else ""} for q in cap.get("questions") or []]
                caps.append({**cap, "requirements": requirements, "questions": questions})
        if caps:
            functions.append({**function, "capabilities": caps})
    return functions, dropped


def number(domains: list[dict[str, Any]]) -> None:
    """Codes per function, as AWS Transform numbers them: REQ-F-001, REQ-N-001, OQ-001."""
    for d_index, domain in enumerate(domains, 1):
        for f_index, function in enumerate(domain["functions"], 1):
            function["id"] = f"claude/{domain['key']}/{f_index:02d}"
            counters = {"functional": 0, "non-functional": 0, "question": 0}
            for c_index, cap in enumerate(function["capabilities"], 1):
                cap["id"] = f"{function['id']}#{c_index}"
                cap["number"] = c_index
                for req in cap["requirements"]:
                    counters[req["kind"]] += 1
                    req["code"] = f"REQ-{'F' if req['kind'] == 'functional' else 'N'}-{counters[req['kind']]:03d}"
                    req["key"] = f"{function['id']}/{req['code']}"
                for question in cap.get("questions") or []:
                    counters["question"] += 1
                    question["code"] = f"OQ-{counters['question']:03d}"
                    question["key"] = f"{function['id']}/{question['code']}"


def generate(folder: RunFolder, claude: ClaudeCode, model: dict[str, Any]) -> dict[str, Any]:
    from reframe.claude.workspace import paths
    saved = folder.load("outputs/claude/requirements.json")
    if saved and saved.get("complete"):
        return saved
    places = paths(folder)
    inputs = places["analysis"] / "reframe"
    inputs.mkdir(parents=True, exist_ok=True)
    lines = file_lines(places["legacy"])
    known = {r["id"] for r in model.get("rules") or []}
    progress = (saved or {}).get("domains") or []
    done_keys = {d["key"] for d in progress}
    totals = (saved or {}).get("steps") or []
    for domain in model.get("domains") or []:
        key = re.sub(r"[^a-z0-9]+", "-", domain["id"].replace("dom:", "").casefold()).strip("-") or "domain"
        if key in done_keys:
            continue
        data = domain_input(model, domain)
        if not data["rules"]:
            progress.append({"key": key, "name": domain["name"], "description": domain.get("description", ""), "functions": [],
                             "dropped": 0, "note": "the plugin wrote no rule cards for this domain"})
            continue
        path = inputs / f"requirements-input-{key}.json"
        path.write_text(json.dumps(data, indent=1))
        result = claude.run(f"requirements-{key}", PROMPT.format(input=f"analysis/{folder.state['project']}/reframe/{path.name}"),
                            timeout=3600, schema=SCHEMA)
        totals.append({"domain": key, **{k: v for k, v in result.as_json().items() if k in ("ok", "seconds", "turns", "tokens", "cost_usd", "problem")}})
        if not result.ok:
            folder.save("outputs/claude/requirements.json", {"label": LABEL, "complete": False, "domains": progress, "steps": totals})
            from reframe.claude.steps import stop_for
            raise stop_for(result, f"requirements for {domain['name']}")
        raw = claude.structured(result) or {}
        functions, dropped = check(raw, known, lines)
        progress.append({"key": key, "name": domain["name"], "description": domain.get("description", ""), "functions": functions,
                         "dropped": dropped, "rules_in": len(data["rules"])})
        folder.save("outputs/claude/requirements.json", {"label": LABEL, "complete": False, "domains": progress, "steps": totals})
    number(progress)
    cited = {r for d in progress for f in d["functions"] for c in f["capabilities"] for q in c["requirements"] for r in q["rules"]}
    value = {"label": LABEL, "complete": True, "generated_at": iso(), "domains": progress, "steps": totals,
             "dropped": sum(d.get("dropped", 0) for d in progress), "rules_cited": len(cited & known), "rules_total": len(known)}
    folder.save("outputs/claude/requirements.json", value)
    folder.event("claude_requirements", functions=sum(len(d["functions"]) for d in progress),
                 requirements=sum(len(c["requirements"]) for d in progress for f in d["functions"] for c in f["capabilities"]),
                 dropped=value["dropped"])
    return value


def failed_stop(text: str) -> Stop:
    return Stop(Outcome.FAILED, text)
